<script setup lang="ts">
import {onMounted,ref} from 'vue';
import {request} from './api';
import {useProject} from './store';
import type {Project,Snapshot,Catalog} from './model';
import {ElMessageBox} from 'element-plus';
interface Version {version_no:number;source_revision:number;created_at:string;note:string;document?:Project}
const store=useProject(),rows=ref<Version[]>([]),selected=ref<Version>(),busy=ref(false),error=ref(''),offset=ref(0),catalog=ref<Catalog>();
const savingVersion=ref(false),note=ref('');
const label=(n:number)=>'W'+String(n).padStart(4,'0');
async function load(){try{rows.value=await request('/api/v1/website-versions?offset='+offset.value);}catch(e){error.value=String(e);}}
async function save(){if(!note.value.trim())return;busy.value=true;error.value='';try{await store.flush();await request('/api/v1/website-versions',{method:'POST',headers:{'If-Match':String(store.revision)},body:JSON.stringify({note:note.value.trim()})});offset.value=0;await load();savingVersion.value=false;note.value='';}catch(e){error.value=String(e);}finally{busy.value=false;}}
async function view(v:Version){try{selected.value=await request('/api/v1/website-versions/'+v.version_no);}catch(e){error.value=String(e);}}
async function restore(v:Version){try{await ElMessageBox.confirm('恢复 '+label(v.version_no)+' 为草稿？当前草稿会先保存为版本，已发布网站保持不变。','恢复版本',{confirmButtonText:'恢复为草稿',cancelButtonText:'取消'});}catch{return;}
 busy.value=true;try{await store.flush();store.accept(await request<Snapshot>('/api/v1/website-versions/'+v.version_no+'/restore',{method:'POST',headers:{'If-Match':String(store.revision)},body:'{}'}));await load();selected.value=undefined;}catch(e){error.value=String(e);}finally{busy.value=false;}}
async function page(direction:number){offset.value=Math.max(0,offset.value+direction*50);await load();}
onMounted(async()=>{await load();catalog.value=await (await fetch('/workspace/catalog.json')).json();});
</script>
<template><section class="card sw-card"><header class="between"><div class="sw-heading-line"><h2>页面与配置版本</h2><p class="small muted">恢复版本会生成新草稿，不替换已上线的网站。</p></div><button class="primary" :disabled="busy" @click="note='';savingVersion=true">保存版本</button></header><div class="sw-policy"><strong>媒体保留规则</strong><span>同名图片、视频只保留最新文件；恢复页面版本时仍使用最新媒体。</span></div><p v-if="error" role="alert" class="error">{{error}}</p><div class="table-scroll"><table><thead><tr><th>版本</th><th>保存时间</th><th>说明</th><th>操作</th></tr></thead><tbody><tr v-for="v in rows" :key="v.version_no"><td>{{label(v.version_no)}}</td><td>{{new Date(v.created_at).toLocaleString()}}</td><td>{{v.note}}</td><td><button @click="view(v)">查看</button> <button :disabled="busy" @click="restore(v)">恢复为草稿</button></td></tr></tbody></table></div><p v-if="!rows.length" class="empty">尚无保存的版本。</p><div v-if="offset||rows.length===50" class="card-actions"><button :disabled="!offset" @click="page(-1)">上一页</button><button :disabled="rows.length<50" @click="page(1)">下一页</button></div></section><el-dialog class="approved-page version-dialog" v-model="savingVersion" title="保存网站版本" width="min(900px,94vw)" :close-on-click-modal="false"><form @submit.prevent="save"><label class="sw-field">版本说明<textarea v-model="note" rows="3" maxlength="500" required placeholder="例如：调整产品栏目、更新公司介绍"></textarea></label><p>保存页面内容、架构、显示方式、语言和配置。图片／视频只使用最新文件。</p><p v-if="error" role="alert" class="error">{{error}}</p><div class="card-actions"><button type="button" @click="savingVersion=false">关闭</button><button class="primary" :disabled="busy">保存版本</button></div></form></el-dialog><el-dialog class="approved-page version-dialog" :model-value="!!selected" :title="selected?'版本 '+label(selected.version_no):''" width="min(900px,94vw)" @close="selected=undefined"><template v-if="selected?.document"><p>{{selected.note}}</p><div class="sw-grid"><p>页面数量：{{selected.document.pages.length}}</p><p>发布语言：{{(selected.document.site?.publishLanguages??selected.document.languages).map(l=>catalog?.languageNames[l]||l).join('、')}}</p></div><ul><li v-for="p in selected.document.pages" :key="p.id">{{p.title}} · {{({list:'列表',tabs:'Tab',carousel:'轮播'})[selected.document.site?.presentations[p.id]?.mode||'list']}}</li></ul><p class="hint">历史页面可恢复，媒体仍指向最新文件。</p><div class="card-actions"><button @click="selected=undefined">关闭</button></div></template></el-dialog></template>
